#GOOGLE
# In Python (Native) mode, incoming items are passed as a standard list named '_items'
items = _items

sql_columns = []

for item in items:
    # item is an n8n dictionary containing your incoming row metadata
    col = item.get('json', {})
    column_name = col.get('column_name')
    allow_null = col.get('allow_null')
    transform_type = col.get('transform_type')
    is_pii = col.get('is_pii')

    # 1. Determine base column or default fallback if NULL is not allowed
    base_expression = column_name
    if allow_null is False or str(allow_null).lower() == 'false':
        fallback = col.get('default_fallback')
        if fallback is None:
            fallback = "''"
        base_expression = f"COALESCE({column_name}, {fallback})"

    # 2. Handle Data Privacy Policy (PII Masking & Hashing)
    if is_pii is True or str(is_pii).lower() == 'true':
        if transform_type == 'hash':
            sql_columns.append(f"encode(sha256({base_expression}::bytea), 'hex') AS {column_name}")
            continue
        elif transform_type == 'mask':
            sql_columns.append(f"CONCAT('XXXX-XXXX-XXXX-', RIGHT({base_expression}::text, 4)) AS {column_name}")
            continue

    # 3. Handle Case Normalization & Numeric Precision/Scale Casting
    if transform_type == 'upper':
        sql_columns.append(f"UPPER({base_expression}::text) AS {column_name}")
    elif transform_type == 'lower':
        sql_columns.append(f"LOWER({base_expression}::text) AS {column_name}")
    elif transform_type == 'capitalize':
        sql_columns.append(f"INITCAP({base_expression}::text) AS {column_name}")
    elif transform_type == 'decimal':
        scale = col.get('decimal_scale') or '10,5'
        sql_columns.append(f"CAST({base_expression} AS DECIMAL({scale})) AS {column_name}")
    else:
        sql_columns.append(f"{base_expression} AS {column_name}")

# Join all generated column selections into a single multi-line text block
select_clause_string = ",\n  ".join(sql_columns)

# Return the single combined string block nested inside an n8n json dictionary structure
return [{
    "json": {
        "select_clause": select_clause_string
    }
}]

